/* Éttermek: az azonosítók előzetes meetingválogatást jelölnek, nem teljes piacot. */
(()=>{'use strict';const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const lk=(u,t='Forrás')=>/^https?:\/\//.test(u||'')?`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)} ↗</a>`:'nem igazolt';const fmt=n=>typeof n==='number'?new Intl.NumberFormat('hu-HU').format(n)+' Ft':'ár nem igazolt';let ids=[['E09','Chill','Közvetlenül az Óváros téren','Chill Bistro'],['E02','Oliva','Történelmi belváros','Oliva'],['E03','Fricska','Városi összehasonlítás','Fricska'],['E06','Gusto 13','Városi bistróreferencia','Gusto 13'],['E20','Skorpió','Belvárosi ebédmenü-összehasonlítás','']];function view(d){let restaurants=d['Éttermek']||[], flow=(d['Dashboard adatfolyam']||[]).slice(1),dist=(d['Distance']||[]).slice(1),deliver=(d['Delivery and hours']||[]).slice(1),lunch=(d['Napi menü árak']||[]).slice(1);let cards=ids.map(([id,match,reason,distKey])=>{let r=restaurants.find(x=>x[0]===id);if(!r)return `<article class="comp-card"><h3>${esc(match)}</h3><p>Az éttermi törzsben nem található; ellenőrzés szükséges.</p></article>`;let ds=distKey?dist.find(x=>String(x[0]||'').startsWith(distKey)):null;let chan=deliver.filter(x=>x[0]==='Delivery presence'&&String(x[1]||'').toLowerCase().includes(match.toLowerCase())&&/^(Wolt|Foodora)$/.test(String(x[2])));let men=lunch.filter(x=>x[1]===id&&x[5]===2&&typeof x[7]==='number'&&x[6]!=='Elvitel');let dishes=flow.filter(x=>x[1]===id&&x[28]==='Önálló fogás'&&x[37]==='Helyszíni'&&typeof x[7]==='number'&&!/pizza|pinsa|felár|köret|savanyúság/i.test(String(x[4])));let examples=[];let seen=new Set();for(let x of dishes){let key=x[25]||x[0];if(seen.has(key))continue;seen.add(key);examples.push(x);if(examples.length>=3)break}return `<article class="comp-card"><span class="pill">${esc(reason)} · előzetes besorolás</span><h3>${esc(r[1])}</h3><p><b>Cím:</b> ${esc(r[3]||'nem igazolt')}</p><p><b>Kínálat:</b> ${esc(r[5]||'nem igazolt')}</p><p><b>Megközelítés:</b> ${ds?`${esc(ds[2])} becsült gyalogos útvonal; légvonalban ${esc(ds[1])}.${id==='E09'?' A térképi útvonal az Óváros téren kerülőt mutathat.':''}`:'Nincs rögzített gyalogos útvonal.'}</p><p><b>Ebédmenü:</b> ${men.length?men.map(x=>`${esc(x[4])}: ${fmt(x[7])} (${esc(x[13]||'?')} – ${esc(x[14]||'?')}; ${esc(x[6]||'csatorna nem egyértelmű')})`).join('; '):esc(r[9]||'Nem ellenőrzött')} ${men.length?'Kiírt ár; a szervizdíj alkalmazása külön ellenőrizendő.':''}</p><p><b>Kiszállítás:</b> ${chan.length?chan.map(x=>`${esc(x[2])}: ${x[3]==='Yes'?'a forrásban megtaláltuk':'ebben a körben nem találtuk'} (${esc(x[5])})${x[6]?' '+lk(x[6]):''}`).join(' · '):'Nem vizsgált vagy nincs egyértelmű párosítás.'}</p><details><summary>Étlappéldák és korlátok</summary><p>Megfigyelt kiírt helyszíni árak, eltérő dátumokkal; adag és érvényesség nem feltétlenül egyezik.</p><ul>${examples.map(x=>`<li>${esc(x[5])} — ${fmt(x[7])} · ellenőrizve: ${esc(x[15]||'nem ismert')} · ${lk(x[16])}</li>`).join('')||'<li>Nincs megfelelően besorolt példa.</li>'}</ul><p>${esc(r[7]||'')} ${esc(r[11]||'')}</p></details><p class="muted">Helyadat ellenőrzése: ${esc(r[12]||'nem ismert')}. ${lk(r[13],'Helyadat')} · ${lk(r[6],'Étlap')}${r[8]?' · '+lk(r[8],'Menü'):''}</p></article>`}).join('');return `<div class="eyebrow">VERSENYTÁRSAK · MEETINGVÁLOGATÁS</div><h1>Kiket érdemes figyelnünk?</h1><p class="section-intro">Öt hely kiindulásként a közös beszélgetéshez. Zsolt és a séf tudják pontosítani, ki számít igazán versenytársnak.</p><div class="warning">A megfigyelések 2026 októberéből és novemberéből származnak. A „nem találtuk” nem jelenti azt, hogy a szolgáltatás biztosan nem érhető el. A gyalogos távolság becslés.</div><div class="comp-grid">${cards}</div><section class="panel"><h2>Vélemények és értékelések</h2><p>A források platformonként és különböző dátumokból származnak. Alább nyithatók meg a rögzített adatok és témák; az értékeléseket nem átlagoljuk össze.</p></section>`}window.competitorView=view})();
